```js
// Filter
const filterInput = document.querySelector("[data-force-filter]");
filterInput.addEventListener("input", () => {
  const q = filterInput.value.trim().toLowerCase();
  document.querySelectorAll("table.matrix tbody tr.force-row").forEach((row) => {
    const hay = (row.getAttribute("data-search") || row.textContent || "").toLowerCase();
    row.hidden = q !== "" && hay.indexOf(q) === -1;
  });
});

// Accordion
document.querySelectorAll("[data-accordion-toggle]").forEach((btn) => {
  btn.addEventListener("click", () => {
    const detail = btn.nextElementSibling;
    if (!detail) return;
    const expanded = btn.getAttribute("aria-expanded") === "true";
    btn.setAttribute("aria-expanded", String(!expanded));
    detail.hidden = expanded;
  });
});

// Sort
function sortMatrixBy(key, dir) {
  const table = document.querySelector("table.matrix");
  const tbody = table && table.querySelector("tbody");
  if (!tbody) return;
  const rows = Array.from(tbody.querySelectorAll("tr.force-row"));
  const mult = dir === "desc" ? -1 : 1;
  rows.sort((ra, rb) => {
    if (key === "force") return (ra.getAttribute("data-force-id") || "").localeCompare(rb.getAttribute("data-force-id") || "") * mult;
    if (key === "total") return (Number(ra.getAttribute("data-row-total") || 0) - Number(rb.getAttribute("data-row-total") || 0)) * mult;
    if (key.indexOf("component:") === 0) {
      const comp = key.slice("component:".length);
      const ca = ra.querySelector('td[data-component="' + CSS.escape(comp) + '"]');
      const cb = rb.querySelector('td[data-component="' + CSS.escape(comp) + '"]');
      const va = ca && ca.getAttribute("data-coupled") === "1" ? 1 : 0;
      const vb = cb && cb.getAttribute("data-coupled") === "1" ? 1 : 0;
      return (va - vb) * mult;
    }
    return 0;
  });
  rows.forEach((row) => tbody.appendChild(row));
}
document.querySelectorAll("table.matrix thead th[data-sort-key]").forEach((th) => {
  const activate = () => {
    const key = th.getAttribute("data-sort-key");
    const current = th.classList.contains("sort-asc") ? "asc" : th.classList.contains("sort-desc") ? "desc" : null;
    const next = current === "asc" ? "desc" : "asc";
    document.querySelectorAll("table.matrix thead th[data-sort-key]").forEach((other) => other.classList.remove("sort-asc", "sort-desc"));
    th.classList.add(next === "asc" ? "sort-asc" : "sort-desc");
    sortMatrixBy(key, next);
  };
  th.addEventListener("click", activate);
  th.addEventListener("keydown", (ev) => { if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); activate(); } });
});

// Fusion/fission
function computeMatrixCandidates() {
  const table = document.querySelector("table.matrix");
  const fusion = new Set(); const fission = new Set();
  if (!table) return { fusion, fission };
  const componentNames = Array.from(table.querySelectorAll("thead th[data-component]")).map((th) => th.getAttribute("data-component"));
  const vectors = {};
  componentNames.forEach((name) => { vectors[name] = {}; });
  table.querySelectorAll("tbody td[data-residue-cell]").forEach((td) => {
    const comp = td.getAttribute("data-component"); const force = td.getAttribute("data-force-id");
    if (vectors[comp]) vectors[comp][force] = td.getAttribute("data-coupled") === "1";
  });
  for (let i = 0; i < componentNames.length; i++) {
    for (let j = i + 1; j < componentNames.length; j++) {
      const a = vectors[componentNames[i]]; const b = vectors[componentNames[j]];
      const forceIds = Object.keys(a);
      const identical = forceIds.length > 0 && forceIds.every((fid) => a[fid] === b[fid]);
      if (identical) { fusion.add(componentNames[i]); fusion.add(componentNames[j]); }
    }
  }
  const thresholdInput = document.querySelector("[data-threshold-input]");
  const threshold = thresholdInput ? Number(thresholdInput.value) : 1;
  table.querySelectorAll("tfoot td[data-col-total]").forEach((td) => {
    const total = Number(td.getAttribute("data-col-total"));
    if (total > threshold) fission.add(td.getAttribute("data-component"));
  });
  return { fusion, fission };
}
function applyFusionFissionHighlighting() {
  const table = document.querySelector("table.matrix");
  if (!table) return;
  const { fusion, fission } = computeMatrixCandidates();
  const componentNames = Array.from(table.querySelectorAll("thead th[data-component]")).map((th) => th.getAttribute("data-component"));
  const onlyToggle = document.querySelector("[data-fusion-fission-filter]");
  const only = !!(onlyToggle && onlyToggle.checked);
  componentNames.forEach((name) => {
    const isFusion = fusion.has(name); const isFission = fission.has(name);
    const show = !only || isFusion || isFission;
    table.querySelectorAll('[data-component="' + CSS.escape(name) + '"]').forEach((el) => {
      el.setAttribute("data-fusion", isFusion ? "1" : "0");
      el.setAttribute("data-fission", isFission ? "1" : "0");
      el.hidden = !show;
    });
  });
}
// init: thresholdInput.min="1", max=String(Math.max(1,numForces)), value=String(Math.max(1,Math.floor(numForces/2))), thresholdOutput.textContent synced;
// re-run applyFusionFissionHighlighting on threshold input event and fusionFissionToggle change event.
```

Adapt: instead of `document.querySelector*`, scope all lookups to `container` (the parameter), so this module doesn't assume it's the only thing on the page. Use event delegation on `container` for click/input/keydown listeners (one listener each, checking `event.target.closest(...)`) so dynamically-added rows/headers/inputs (from `matrix-interactions.ts`/`forms.ts`, which insert new `tr`/`th` elements after this mounts) are handled without needing to re-run `mountMatrixView`. `recomputeFusionFission()` (the returned handle method) should just be `applyFusionFissionHighlighting` scoped to `container`, callable on demand by `main.ts`'s shared `onChange`.

Read the test file closely for exact expected behavior/edge cases (e.g. whether hidden `<span>`/text nodes inside filter-search matter, whether the "component:" sort test expects a specific tie-break, whether keyboard test dispatches a real `KeyboardEvent`) — implement to match the tests exactly, not just the paraphrased JS above (the tests are the ground truth; the JS above is a faithful reference for the ORIGINAL behavior being restored, but the test file is what's graded).

